// Appends one complete frame (header, payload, CRC) for `message` to `out`.
// `version` selects the protocol version to speak; it must not be older than the
// message's introduction (M::kSince) nor newer than kVersion.
template <typename M>
[[nodiscard]] Status encode_frame(const M& message, std::vector<std::uint8_t>& out,
                                  std::uint8_t version = kVersion) {
    if (version == 0U || version > kVersion || version < M::kSince) {
        return Status::UnsupportedVersion;
    }
    std::vector<std::uint8_t> frame(kHeaderSize + M::kWireSize + kCrcSize);
    Writer writer(frame.data(), frame.size());
    writer.put<kFrameEndian>(kSync);
    writer.put<kFrameEndian>(version);
    writer.put<kFrameEndian>(M::kId);
    writer.put<kFrameEndian>(static_cast<std::uint16_t>(M::kWireSize));
    const Status payload_status = message.encode(writer);
    if (payload_status != Status::Ok) return payload_status;
    writer.put<kFrameEndian>(frame_crc(frame.data() + 1, kHeaderSize - 1U + M::kWireSize));
    if (writer.status() != Status::Ok) return writer.status();
    out.insert(out.end(), frame.begin(), frame.end());
    return Status::Ok;
}

namespace detail {

template <typename M>
[[nodiscard]] Status decode_payload(const std::uint8_t* data, std::size_t size,
                                    std::uint8_t version, Message& out) {
    if (version < M::kSince) return Status::UnsupportedVersion;
    if (size != M::kWireSize) return Status::BadLength;
    Reader reader(data, size);
    M message;
    const Status status = message.decode(reader);
    if (status == Status::Ok) out = std::move(message);
    return status;
}

}  // namespace detail

// Decodes the frame at the start of [data, data + size). On success `consumed`
// (if given) receives the frame length; it is left untouched on failure.
// Truncated means more bytes are needed; any other error means the frame is bad.
[[nodiscard]] inline Status decode_frame(const std::uint8_t* data, std::size_t size, Message& out,
                                         std::size_t* consumed = nullptr) {
    if (size < kHeaderSize) {
        return (size > 0 && data[0] != kSync) ? Status::BadSync : Status::Truncated;
    }
    Reader header(data, kHeaderSize);
    std::uint8_t sync{};
    std::uint8_t version{};
    std::uint16_t id{};
    std::uint16_t length{};
    header.get<kFrameEndian>(sync);
    header.get<kFrameEndian>(version);
    header.get<kFrameEndian>(id);
    header.get<kFrameEndian>(length);
    if (sync != kSync) return Status::BadSync;
    if (version == 0U || version > kVersion) return Status::UnsupportedVersion;
    const std::size_t total = kHeaderSize + static_cast<std::size_t>(length) + kCrcSize;
    if (size < total) return Status::Truncated;
    Reader trailer(data + kHeaderSize + length, kCrcSize);
    Crc expected{};
    trailer.get<kFrameEndian>(expected);
    if (frame_crc(data + 1, kHeaderSize - 1U + length) != expected) return Status::BadCrc;

    const std::uint8_t* payload = data + kHeaderSize;
    Status status = Status::UnknownMessage;
    switch (id) {
        case Heartbeat::kId:
            status = detail::decode_payload<Heartbeat>(payload, length, version, out);
            break;
        case Attitude::kId:
            status = detail::decode_payload<Attitude>(payload, length, version, out);
            break;
        case GpsFix::kId:
            status = detail::decode_payload<GpsFix>(payload, length, version, out);
            break;
        case ImuSample::kId:
            status = detail::decode_payload<ImuSample>(payload, length, version, out);
            break;
        case Command::kId:
            status = detail::decode_payload<Command>(payload, length, version, out);
            break;
        case CommandAck::kId:
            status = detail::decode_payload<CommandAck>(payload, length, version, out);
            break;
        case BatteryStatus::kId:
            status = detail::decode_payload<BatteryStatus>(payload, length, version, out);
            break;
        default: break;
    }
    if (status == Status::Ok && consumed != nullptr) *consumed = total;
    return status;
}

[[nodiscard]] inline const char* message_name(const Message& message) noexcept {
    return std::visit([](const auto& m) { return std::decay_t<decltype(m)>::kName; }, message);
}

